from PIL import Image, ImageDraw, ImageFont
import json, math, textwrap

W,H = 2200,1200
img = Image.new('RGB',(W,H),'white')
d = ImageDraw.Draw(img)

with open('/app/benchmark/source_data.json') as f:
    data=json.load(f)

nodes={n['id']:n for n in data['pipeline_nodes']['data']}
edges=data['pipeline_edges']['data']
lanes=['dev','staging','canary','production']
lane_y={'dev':270,'staging':480,'canary':690,'production':900}

main=[n for n in nodes.values() if n['lane'] in lanes and n['order']<100]
main=sorted(main,key=lambda x:x['order'])

def x_from_order(o):
    return 120 + (o-1)*68

x={n['id']:x_from_order(n['order']) for n in main}
y={nid:lane_y[n['lane']] for nid,n in nodes.items() if n.get('lane') in lanes}

x.update({'rollback-dev':x_from_order(7)+70,'rollback-staging':x_from_order(12)+70,'rollback-canary':x_from_order(19)+70,'rollback-prod':x_from_order(24)+70,'hpa-scale-up':2060,'hpa-scale-down':2060})
y.update({'rollback-dev':lane_y['dev'],'rollback-staging':lane_y['staging'],'rollback-canary':lane_y['canary'],'rollback-prod':lane_y['production'],'hpa-scale-up':130,'hpa-scale-down':1060})

try:
    f_title=ImageFont.truetype('/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf',42)
    f_sub=ImageFont.truetype('/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf',24)
    f_lane=ImageFont.truetype('/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf',24)
    f_node=ImageFont.truetype('/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf',14)
    f_small=ImageFont.truetype('/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf',12)
except:
    f_title=f_sub=f_lane=f_node=f_small=ImageFont.load_default()

lane_bg={'dev':'#F6F8FA','staging':'#F1F6FC','canary':'#F8F4FC','production':'#F2F9F4'}
for lane in lanes:
    yy=lane_y[lane]
    d.rounded_rectangle((40,yy-85,2120,yy+85),radius=18,fill=lane_bg[lane],outline='#D0D7DE',width=2)
    d.text((55,yy-112),lane.upper(),fill='#344054',font=f_lane)

d.text((1500,92),'GLOBAL HPA ACTIONS',fill='#667085',font=f_small)

colors={'action':'#2F6DB3','check':'#0E9384','decision':'#7A5AF8','hpa_decision':'#C96F00','rollback':'#C81E1E','terminal':'#137333','hpa_action':'#B54708'}

def draw_arrow(x1,y1,x2,y2,color,width=3,dashed=False,curve=0):
    if curve==0:
        if dashed:
            steps=18
            for i in range(steps):
                if i%2==0:
                    xa=x1+(x2-x1)*i/steps; ya=y1+(y2-y1)*i/steps
                    xb=x1+(x2-x1)*(i+1)/steps; yb=y1+(y2-y1)*(i+1)/steps
                    d.line((xa,ya,xb,yb),fill=color,width=width)
        else:
            d.line((x1,y1,x2,y2),fill=color,width=width)
    else:
        cx=(x1+x2)/2; cy=(y1+y2)/2 + curve
        pts=[]
        for t in [i/30 for i in range(31)]:
            xa=(1-t)*(1-t)*x1+2*(1-t)*t*cx+t*t*x2
            ya=(1-t)*(1-t)*y1+2*(1-t)*t*cy+t*t*y2
            pts.append((xa,ya))
        for i in range(len(pts)-1):
            if (not dashed) or i%2==0:
                d.line((pts[i][0],pts[i][1],pts[i+1][0],pts[i+1][1]),fill=color,width=width)
    ang=math.atan2(y2-y1,x2-x1)
    ah=12
    p1=(x2,y2)
    p2=(x2-ah*math.cos(ang-0.45),y2-ah*math.sin(ang-0.45))
    p3=(x2-ah*math.cos(ang+0.45),y2-ah*math.sin(ang+0.45))
    d.polygon([p1,p2,p3],fill=color)

for e in edges:
    a,b=e['from'],e['to']
    if a not in x or b not in x or a not in y or b not in y: continue
    et=e['type']
    col='#4B5563'; dash=False; curve=0
    if et=='rollback': col='#C81E1E'; dash=True; curve=40
    elif et=='hpa_branch': col='#B54708'; dash=True; curve=-60 if y[b]>y[a] else 60
    elif et=='blue_green': col='#006D77'; curve=-45
    draw_arrow(x[a]+28,y[a],x[b]-28,y[b],col,3,dash,curve)
    lbl=e.get('label','').strip()
    if lbl and et in ('rollback','blue_green'):
        d.text(((x[a]+x[b])//2-70,(y[a]+y[b])//2-28),lbl,fill=col,font=f_small)

for nid,n in nodes.items():
    if nid not in x or nid not in y: continue
    xx,yy=x[nid],y[nid]
    t=n['type']
    if t=='decision':
        s=28
        d.polygon([(xx,yy-s),(xx+s,yy),(xx,yy+s),(xx-s,yy)],outline=colors[t],fill='white',width=3)
    else:
        d.rounded_rectangle((xx-42,yy-24,xx+42,yy+24),radius=8,outline=colors[t],fill='white',width=3)
    label=n['label']
    if t=='hpa_decision': label += f"\nCPU>{n['cpu_threshold_pct']}% MEM>{n['mem_threshold_pct']}%"
    if t=='decision' and 'error_rate_threshold_pct' in n:
        extra=f"Err>{n['error_rate_threshold_pct']}%"
        if 'p99_latency_ms_threshold' in n: extra += f" P99>{n['p99_latency_ms_threshold']}ms"
        label += f"\n{extra}"
    lines=[]
    for part in label.split('\n'):
        lines += textwrap.wrap(part,width=18) or ['']
    y0=yy-8*len(lines)
    for i,ln in enumerate(lines[:4]):
        d.text((xx-38,y0+i*15),ln,fill='#111827',font=f_small)

legend=[('Action Step','#2F6DB3',False),('Check/Test','#0E9384',False),('Decision Gate','#7A5AF8',False),('HPA Decision (CPU% / MEM%)','#C96F00',False),('Auto Rollback Path','#C81E1E',True),('Blue-Green Switch Flow','#006D77',False)]
lx,ly=130,1135
for name,col,dash in legend:
    if dash:
        for i in range(6):
            if i%2==0:d.line((lx+i*12,ly,lx+(i+1)*12,ly),fill=col,width=4)
    else:
        d.line((lx,ly,lx+70,ly),fill=col,width=4)
    d.text((lx+82,ly-12),name,fill='#344054',font=f_sub)
    lx += 340

d.text((40,20),'Kubernetes Multi-Environment Deployment Pipeline',fill='#101828',font=f_title)
d.text((40,70),'Swimlane flow with rollback paths, HPA checkpoints (CPU%/MEM%), and production blue-green cutover decision',fill='#475467',font=f_sub)

d.text((980,1035),'X-axis: Pipeline Progression Order (sequence index)',fill='#475467',font=f_sub)
d.text((6,560),'Environment Swimlanes',fill='#475467',font=f_sub)

img.save('/app/output/result.png')
print('saved /app/output/result.png')
